      "raw_content": "카페홈\n좌담회/설문/주부알바\n가입\n검색\n메뉴\n▶좌담회 신청하기(당일 현금지급)\n앱 열기\n▶10/20~23) 공공기관 관련 인지도 및 홍보 좌담회 / 남녀\n본문 기타 기능\n하늘\n카페매니저\n채팅\n작성일\n2026.10.20. 21:02\n조회 67\n▶10/20~23) 공공기관 관련 인지도 및 홍보 좌담회 / 남녀\n=====================================\n공공기관 관련 인지도 및 홍보관련하여 일반국민 의견을 들어보고자 좌담회를 진행합니다.\n좌담회는 약 2시간 소요되며, 참석자에게는 10만원 백화점 상품권이 지급됩니다.\n정확한 대상자 선정을 위하여 아래 질문을 여쭈어보고 참석대상이 되시는 분에게는 개별연락을 드립니다.\n예비대상자 선정 후 보내드리는 사전과제를 정해진 기일안에 제출하시면 최종 참석자로 선정됩니다.\n정확한 응답해주시기 바랍니다.\n인원이 조기 마감되는 경우 일일이 전화 드리지 못하는 점 양해부탁드립니다.\n[응답하신 내용 중 개인 관련 내용은 외부에 유출되지 않으며, 통계법에 의거하여 비밀이 보장됩니다.]\n모집일정 : 2026년 10월 20일 ~ 10월 23일\n참석비 : 모바일 10만원 백화점 상품권 지급\n-------------------------------------------------------------------\n==>소개자란[김현숙]을 반드시 입력해야 신청완료 됩니다.\n(간혹 소개자란에 본인 이름, 지인 이름, 없음, 네이버 카페... 이런식으로 적으면 접수 안 됩니다.)\n[아래 URL에 (클릭!!)하여 설문 진행해주세요.(스마트폰도 가능)\nhttps://forms.gle/oGhiHCtvqsATEiMNA\n좋아요\n1\n좋아요한 사람 목록으로 이동\n'좋아요'로 마음을 나누세요!\n논현동 이웃끼리 공유하는 동네 꿀정보\n댓글\n0\n클린봇 이 악성 댓글을 감지합니다.\n지금 가입하고 댓글에 참여해보세요!\n전체글\n▶10/20~23) 공공기관 관련 인지도 및 홍보 좌담회 / 남녀\n하늘\n26.10.20.\n댓글\n0\n▶10/29~11/6)초등학교 고학년(5학년,6학년)자녀 대상 금융 이용행태 인터뷰\n하늘\n26.10.20.\n댓글\n0\n▶11/9~10)게임 플레이테스트 참여자 모집 / 만 20~39세 플레이어\n하늘\n26.10.20.\n댓글\n0\n▶10/26~28) 맛테스트 / 30대, 50대 여성\n하늘\n26.10.20.\n댓글\n0\n목록으로\n좋아요\n1\n좋아요한 사람 목록으로 이동\n댓글\n0\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
