      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n10/17~25) 콘텐츠 좌담회-캐릭터\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.10.20. 22:20\n조회 33\n구독\n10/17~25) 콘텐츠 좌담회-캐릭터\n▶ 수행사 : ㈜엔알ㅇㅇ\n▶ 조사목적 : 콘텐츠산업 6개 장르 노동환경 실태 종합적 파악 및 시계열 자료 축적, 콘텐츠산업 구조 변화에 따른 고용구조, 계약 구조 및 인력 활용 방식 특성, 변화 양상 분석\n▶ 진행내용 :\n1) 모더레이터가 사전에 확보한 정보를 바탕으로 참석자의 세부 직무와 경력 범위를 간단히 소개\n2) 주제 1 : 고용 형태와 내부 및 외부 참여 인력의 실제 노무 제공 관계 (약 15분 예상)\n3) 주제 2 : 업무 수행 방식과 노동시간, 자율성, 조직문화 및 안전 조건(약 25분 예상)\n4) 주제 3 : 계약 방식과 실제 업무 범위, 보상 조건(약 15분 예상)\n5) 주제 4 : 사회보장과 고용 및 경력 지속 조건(약 10분 예상)\n6) 주제 5 : AI 활용 현황 및 노동환경 변화(약 30분 예상)\n7) 주제 6 : 노동환경 문제 대응과 정책 및 제도 이용(약 20분 예상)\n총 2시간 소요 예상\n▶ 진행방식 : 동일 장르 ( 만화웹툰, 캐릭터) 및 팀장 및 팀원급 FGI를 구분하여 진행\n행)\n(* 장소/일정 변경 시, 개별적으로 연락드릴 예정)\n* FGI에 참여해주신 분들께는 약 10만 원 상당의 답례(모바일 상품권)가 지급될 예정입니다.\n* FGI 진행 장소 : CKL기업지원센터(서울 중구 청계천로 40) 혹은 서울역 인근 회의실\n만화/웹툰 : 21일(수), 22일(목), 23일(금) 19-21시, 24일(토), 25일(일)\n캐릭터 :21일(수), 22일(목), 23일(금) 19-21시, 24일(토), 25일(일)\nhttps://forms.gle/D7UEiEgM4fd8YmXR6\n좋아요\n0\n송파구의 더 많은 인기글 보러가기\n댓글\n0\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n첫 댓글을 남겨보세요\n전체글\n10/17~25) 콘텐츠 좌담회-만화/웹툰\n좌담회알바좌담회카페\n26.10.20.\n댓글\n0\n10/17~25) 콘텐츠 좌담회-캐릭터\n좌담회알바좌담회카페\n26.10.20.\n댓글\n0\n여성 가맹점주 전화 인터뷰\n좌담회알바좌담회카페\n26.10.20.\n댓글\n0\n남성 가맹점주 전화 인터뷰\n좌담회알바좌담회카페\n26.10.20.\n댓글\n0\n새로운 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n0\n댓글\n0\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
