      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n고유링크)7시간 x 2일, 45만원) 11/7~8) 고3 청소년 대상 게임 플레이테스트 조사\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.10.20. 22:26\n조회 14\n구독\n고유링크)7시간 x 2일, 45만원) 11/7~8) 고3 청소년 대상 게임 플레이테스트 조사\n고유링크)7시간 x 2일, 45만원) 11/7~8) 중3~고3 청소년 대상 게임 플레이테스트 조사\n모집이 마감되면 링크가 열리지 않으니 참고 부탁드립니다 ~\n- 조사 대상 :\n1. PC게임을 주 1시간 이상 하며, 롤(PC) 누적 플레이 시간이 20시간 미만인 중3~고3 남녀 (08~11년생)\n2. 본인의 생각을 구체적으로 표현할 수 있는 자\n- 조사 일정 : 11월 7일 (토) ~ 11월 8일 (일) 10:00~17:30 (하루 약 7시간씩 x 2일) (*양일 모두 참석 필수)\n- 진행 방식 : 좌담회 1시간 x 2번 + 게임 플레이테스트 진행 (하루 기준)\n※ 안내사항\n- 해당 조사는 토~일 이틀간 진행됩니다. 양일 모두 참석 가능한 분만 신청 부탁드립니다.\n- 본 조사는 당일 불참자 발생 가능성을 고려하여 예비 인원을 포함해 모집하고 있습니다. 실제 참석 인원이 운영 가능 인원을 초과할 경우, 일부 참여자께서는 테스트에 참여하지 못하고 귀가하실 수 있습니다.\n해당 경우에도 현장 방문에 대한 별도 사례비를 지급해 드릴 예정이니 사전에 내용을 확인하시고 신청 부탁드립니다. (참석 여부는 당일 선발 되므로, 사전에 안내드리기 어려운 점 양해 부탁드립니다.)\n조사장소 강남구 논현동 한국리서치 본사 (9호선:언주역)\n조사기간 2026-11-07 ~ 2026-11-08\n소요시간 7시간 x 2일\n사례비 450,000원\n조사방법 게임플레이스트 + 좌담회 (하루 7시간씩, 이틀간 총 14시간 진행)\n안내사항\n- 2008~2011년생 중고등학생을 대상으로 하는 게임 플레이테스트 조사입니다.\n- 해당 조사는 삼성역 인근 장소에서 11월 7일 (토) ~ 8일 (일) 이틀 모두 하루 약 7시간 동안 진행되며, 이틀 모두 조사에 참석 가능하신 분만 신청 부탁드립니다.\n- 친구와 함께 참여 가능합니다.\n조사 참여 고유링크\nhttps://www.hrc-ms.com/participate/improSurvey/815?refuser=23341&intro=2\n좋아요\n0\n송파구 이웃끼리 공유하는 동네 꿀정보\n댓글\n0\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n첫 댓글을 남겨보세요\n전체글\n고유링크)7시간 x 2일, 45만원) 11/7~8) 고2 청소년 대상 게임 플레이테스트 조사\n좌담회알바좌담회카페\n26.10.20.\n댓글\n0\n고유링크)7시간 x 2일, 45만원) 11/7~8) 고3 청소년 대상 게임 플레이테스트 조사\n좌담회알바좌담회카페\n26.10.20.\n댓글\n0\n고유링크)7시간 x 2일, 45만원) 11/7~8) 중3 청소년 대상 게임 플레이테스트 조사\n좌담회알바좌담회카페\n26.10.20.\n댓글\n0\n10/17~25) 콘텐츠 좌담회-만화/웹툰\n좌담회알바좌담회카페\n26.10.20.\n댓글\n0\n좌담회알바좌담회카페\n 님\n의 글을 3개 보셨네요. 👀\n구독하고 새로운 글을 놓치지 마세요!\n멤버 구독하기\n목록으로\n좋아요\n0\n댓글\n0\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
