      "raw_content": "# # 전동칫솔 사용가구 대상 홈비짓\n# 대상조건:\n– 만 35세 ~ 49세 기혼 여성 (전업주부, 취업 여성, 파트타이머 모두 신청 가능)\n– 거주 지역: 서울특별시 강남구, 서초구, 송파구 소재 아파트 거주자\n– 자녀 조건: 유치원생 ~ 초등학교 저학년(1~3학년) 자녀를 양육 중인 가정\n– 소득 수준: 가구 소득 중상위 해당 가구 (맞벌이 합산 기준)\n– 사용 제품: 가구 내에서 전동칫솔 또는 일반칫솔을 실제 사용하고 계신 분\n– 성향: 낯선 사람과도 편하게 대화하며 본인의 일상생활과 생각을 적극적으로 공유해 주실 수 있는 분\n# 일정 및 소요시간\n– 일정: 10월 30일 금요일 오전 9시 ~ 11시 사이 (시간 조율 가능)\n– 소요시간: 약 60분 내외\n# 사례비 안내\n– 지급 금액: 120,000원 (12만원)\n– 지급 방식: 조사 완료 후 1주일 이내 지정 계좌로 입금\n– 참고 사항: 기타소득세 신고를 위한 주민등록번호 수집이 필수적으로 진행됩니다.\n# 진행 장소\n– 대상자 자택 방문\n– 방문 인원: 진행자 및 연구 관계자 총 5명 (외공인 관계자 1명 포함)\n# 상세 조사 내용 및 제출 항목\n– 조사 내용: 가족의 양치 및 구강 관리 습관 인터뷰, 욕실 및 세면대 등 칫솔 사용 공간 관찰, 라이프스타일 관련 대화\n– 기록 방식: 연구 분석용 사진 및 영상 촬영 진행 (외부 절대 미공개, 순수 연구 목적 외 미사용)\n– 증빙 사진 요청: 사전 확인을 위한 사진 제출 필요 (욕실 전체 사진 여러 각도 다수, 거실 사진 1장, 주방 사진 1장, 칫솔 거치 상태 사진 여러 장)\n참가를 원하시는 분은 아래 버튼을 눌러 신청해 주세요.\n좌담회 신청하기 ➜\n글 탐색\nSNS 관련 조사\n신규 AI 서비스 수용도 조사(다이어리+좌담회)",
